import { useMemo } from 'react';

import { FieldProps } from 'components/Filter/types';
import {
  findFilterClearSentinelOption,
  shouldShowFilterSelectClearIndicator,
} from 'components/Filter/utils/filterClearableSelectPolicy';
import { resolveFilterSelectDisplayValue } from 'components/Filter/utils/filterSelectDisplayValue';
import { Select } from 'components/Form';
import { FilterDataAccessor } from 'domain/Filter/FilterDataAccessor';
import { useGoogleAnalytics, usePageFilterData } from 'hooks';
import { Option } from 'models/Filters';

export const RegionField = ({
  dataTestId,
  fieldKey,
  pageName,
  onValueChange,
  getCurrentValue,
}: FieldProps) => {
  const trackGA = useGoogleAnalytics();
  const { dataFilters, defaults = {} } = usePageFilterData(pageName);
  const countryValue = getCurrentValue('country');
  const currentValue = getCurrentValue(fieldKey);

  const options: Option[] = useMemo(
    () =>
      FilterDataAccessor.getInstance().getOptions(fieldKey, dataFilters, {
        country: countryValue,
      }) as Option[],
    [fieldKey, dataFilters, countryValue],
  );

  const defaultFromPage = defaults[fieldKey];

  const displayValue = resolveFilterSelectDisplayValue(
    options,
    currentValue,
    defaultFromPage,
  );

  const handleValueChange = (option: Option) => {
    if (!option?.value) return;

    trackGA({
      event_category: 'Region Select',
      event_action: 'Select',
      event_label: option.value as string,
    });
    onValueChange(fieldKey, option);
  };

  const clearable = shouldShowFilterSelectClearIndicator(
    pageName,
    fieldKey,
    String(displayValue ?? ''),
    options,
    defaults,
  );

  return (
    <Select
      dataTestId={dataTestId ? `${dataTestId}-${fieldKey}` : undefined}
      id={`${fieldKey}-select`}
      label="Region"
      value={displayValue}
      options={options}
      clearable={clearable}
      onValueChange={(option) => {
        const opt = Array.isArray(option) ? option[0] : option;
        if (opt !== '') {
          handleValueChange(opt as Option);
          return;
        }
        const target = findFilterClearSentinelOption(
          fieldKey,
          options,
          defaults,
        );
        if (!target?.value) {
          return;
        }
        handleValueChange(target);
      }}
      placeholder="Select a Region"
      searchable={options.length > 6}
      disabled={options.length === 0}
    />
  );
};
